using namespace std;

// Version optimisée pour les doublons
void optimizedSort(vector<int>& arr) {
    if (arr.empty()) return;

    // Utilisation d'un tri à 3 voies (3-way partition)
    int lt = 0, gt = arr.size() - 1;
    int i = 0;
    int pivot = arr[0];

    while (i <= gt) {
        if (arr[i] < pivot) {
            swap(arr[lt++], arr[i++]);
        } else if (arr[i] > pivot) {
            swap(arr[i], arr[gt--]);
        } else {
            i++;
        }
    }
    // Tri récursif des partitions
    vector<int> left(arr.begin(), arr.begin() + lt);
    vector<int> right(arr.begin() + gt + 1, arr.end());
    optimizedSort(left);
    optimizedSort(right);
}

