void testQuickSort() {
    vector<int> arr = {3, 6, 8, 10, 1, 2, 1};
    cout << "Original array: ";
    for (int num : arr) cout << num << " ";
    cout << endl;

    optimizedSort(arr);

    cout << "Sorted array: ";
